const root = document.documentElement;
const oldPurple = root.style.getPropertyValue('--purple');
const oldPriority = root.style.getPropertyPriority('--purple');
root.style.setProperty('--purple', '#df80ff');
const removeStyle = xlink.addStyle(`
  .card { box-shadow: 0 0 24px #b65cff24, 0 12px 40px #0002 !important; }
  .nav.active { border-color: #df80ff !important; }
`);
xlink.log('Purple Glow theme enabled (Misc plugin)');
return () => {
  removeStyle();
  if (oldPurple) root.style.setProperty('--purple', oldPurple, oldPriority);
  else root.style.removeProperty('--purple');
  xlink.log('Purple Glow theme disabled');
};
